export function createDiscovery(api,{root,notice,getUser}){
 if(!document.querySelector('link[href="discovery.css"]')){const l=document.createElement('link');l.rel='stylesheet';l.href='discovery.css';document.head.append(l);}
 if(!document.querySelector('link[href="discovery-features.css"]')){const l=document.createElement('link');l.rel='stylesheet';l.href='discovery-features.css';document.head.append(l);}
 if(!document.querySelector('link[href="photo.css"]')){const l=document.createElement('link');l.rel='stylesheet';l.href='photo.css';document.head.append(l);}
 const tab=document.createElement('button');tab.id='people-tab';tab.className='tab';tab.type='button';tab.setAttribute('aria-pressed','false');tab.textContent='Poznaj ludzi';root.querySelector('nav.tabs').insertBefore(tab,root.querySelector('#account-tab'));
 const panel=document.createElement('section');panel.id='people-panel';panel.hidden=true;panel.innerHTML='<div class="card"><span class="step">POZNAJ KOGOŚ</span><h2>Ludzie blisko Ciebie</h2><p class="muted">Rozmowa jest dostępna dopiero po wzajemnym dopasowaniu.</p><details><summary class="create-summary">Ustaw moją wizytówkę</summary><form id="discovery-form"><label>Nazwa widoczna dla innych <small>musi być unikalna</small></label><input name="display_name" minlength="2" maxlength="40" required><label>Miasto</label><input name="city" minlength="2" maxlength="80" required><label>Krótko o mnie</label><textarea name="bio" minlength="10" maxlength="500" rows="4" required></textarea><label>Zainteresowania, oddzielone przecinkami</label><input name="interests" required><label>Pytanie profilowe <small>opcjonalne</small></label><select name="prompt_question"><option value="">Bez pytania</option><option>Idealna niedziela to…</option><option>Najbardziej spontaniczna rzecz, jaką zrobiłem/am…</option><option>Dogadamy się, jeśli…</option><option>Moje małe szczęście to…</option><option>Zapytaj mnie o…</option></select><label>Moja odpowiedź</label><textarea name="prompt_answer" maxlength="240" rows="3" placeholder="Odpowiedz, aby łatwiej było zacząć rozmowę"></textarea><label>Zdjęcie (JPG, PNG lub WebP, maks. 2 MB)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><label class="checkbox"><input name="visible" type="checkbox" checked> Pokazuj moją wizytówkę innym</label><button class="primary" type="submit">Zapisz wizytówkę</button></form></details><form id="discovery-filters" class="search-grid"><label>Filtr miasta</label><input name="city" maxlength="80" placeholder="Dowolne miasto"><label>Filtr zainteresowania</label><input name="interest" maxlength="40" placeholder="Np. spacer"><button class="secondary" type="submit">Zastosuj filtry</button></form><div id="discovery-card" class="discovery-card" hidden></div><p id="discovery-empty" class="muted">Brak nowych osób dla tych filtrów.</p><label class="like-note">Notatka do polubienia <small>opcjonalna; widoczna dopiero po dopasowaniu</small><textarea id="discovery-note" maxlength="150" rows="2" placeholder="Np. Też uwielbiam górskie wyprawy!"></textarea></label><div class="swipe-actions"><button id="discovery-pass" class="secondary" type="button">✕ Pomiń</button><button id="discovery-like" class="primary" type="button">♥ Chcę poznać</button></div><button id="discovery-undo" class="text-button undo-pass" type="button">Cofnij pominięcie (zostały 2)</button><div class="safety-actions"><button id="discovery-report" class="text-button" type="button">Zgłoś osobę</button><button id="discovery-block" class="text-button danger" type="button">Zablokuj osobę</button></div><h3>Moje dopasowania i rozmowy</h3><p id="matches-empty" class="muted">Nie masz jeszcze wzajemnych dopasowań.</p><div id="matches-list"></div><details id="blocked-details"><summary class="create-summary">Zablokowane osoby</summary><p id="blocked-empty" class="muted">Nie blokujesz nikogo.</p><div id="blocked-list"></div></details></div>';root.insertBefore(panel,root.querySelector('#account-panel'));
 const preferences=document.createElement('fieldset');preferences.className='preference-fields';preferences.innerHTML='<legend>Dopasowania</legend><div class="preference-grid"><label>Mój wiek<input name="age" type="number" min="18" max="99" placeholder="18+"></label><label>Przedstawiam się jako<select name="identity"><option value="woman">Kobieta</option><option value="man">Mężczyzna</option><option value="nonbinary">Osoba niebinarna</option><option value="other">Inna / nie podaję</option></select></label><label>Szukam<select name="looking_for"><option value="all">Wszystkich</option><option value="woman">Kobiet</option><option value="man">Mężczyzn</option><option value="nonbinary">Osób niebinarnych</option><option value="other">Innych osób</option></select></label><label>Cel znajomości<select name="relationship_goal"><option value="friends">Przyjaźń</option><option value="dating">Randki</option><option value="relationship">Stały związek</option><option value="activities">Wspólne aktywności</option></select></label><label>Wiek od<input name="min_age" type="number" min="18" max="99" value="18"></label><label>Wiek do<input name="max_age" type="number" min="18" max="99" value="99"></label><label>Zasięg<select name="max_distance_km"><option value="5">5 km</option><option value="10">10 km</option><option value="25">25 km</option><option value="50">50 km</option><option value="100" selected>100 km</option><option value="500">Cała Polska</option></select></label></div><div class="location-tools"><p id="location-status" class="fine">Lokalizacja nie jest zapisana. Bez niej zasięg kilometrów nie ogranicza wyników.</p><button id="set-location" class="secondary" type="button">Użyj mojej lokalizacji</button><button id="clear-location" class="text-button" type="button">Usuń lokalizację</button></div></fieldset>';panel.querySelector('input[name="interests"]').after(preferences);
 const photoTools=document.createElement('div');photoTools.id='current-photo';photoTools.className='current-photo';photoTools.hidden=true;photoTools.innerHTML='<img alt="Obecne zdjęcie wizytówki"><button id="remove-photo" class="text-button danger" type="button">Usuń obecne zdjęcie</button>';panel.querySelector('input[name="photo"]').after(photoTools);
 const $=id=>root.querySelector('#'+id);let cards=[],profile=null,dragging=false,dragStart=0,dragX=0,undosLeft=2;
 const tags=(el,v)=>el.replaceChildren(...(v||[]).map(x=>{const s=document.createElement('span');s.className='interest-tag';s.textContent=x;return s;}));
 function image(path,name){if(!path)return null;const i=document.createElement('img');i.className='discovery-photo';i.src=api.avatarUrl(path);i.alt='Zdjęcie '+name;i.loading='lazy';return i;}
 function promptBlock(r){if(!r.prompt_question||!r.prompt_answer)return null;const q=document.createElement('div');q.className='profile-prompt';const strong=document.createElement('strong');strong.textContent=r.prompt_question;const answer=document.createElement('p');answer.textContent=r.prompt_answer;q.append(strong,answer);return q;}
 const goalLabel=v=>({friends:'Przyjaźń',dating:'Randki',relationship:'Stały związek',activities:'Wspólne aktywności'}[v]||'Poznawanie ludzi');
 function profileMeta(r){const parts=[r.age?r.age+' lat':null,goalLabel(r.relationship_goal),r.distance_km!=null?'około '+r.distance_km+' km':null].filter(Boolean);if(!parts.length)return null;const p=document.createElement('p');p.className='profile-meta';p.textContent=parts.join(' · ');return p;}
 function paintCard(){const box=$('discovery-card'),r=cards[0];box.replaceChildren();box.hidden=!r;box.style.transform='';box.classList.remove('drag-like','drag-pass');$('discovery-empty').hidden=!!r;$('discovery-note').disabled=!r;for(const id of ['discovery-pass','discovery-like','discovery-report','discovery-block'])$(id).disabled=!r;if(!r)return;const hint=document.createElement('span');hint.className='swipe-hint';hint.textContent='Przesuń w lewo lub prawo';const h=document.createElement('h3');h.textContent=r.display_name;const c=document.createElement('p');c.className='discovery-city';c.textContent='📍 '+r.city;const b=document.createElement('p');b.className='discovery-bio';b.textContent=r.bio;const t=document.createElement('div');t.className='interest-list';tags(t,r.interests);box.append(...[image(r.photo_path,r.display_name),h,c,profileMeta(r),b,promptBlock(r),t,hint].filter(Boolean));}
 async function openChat(r,box){let area=box.querySelector('.chat-area');if(area){area.remove();box.classList.remove('chat-open');return;}box.classList.add('chat-open');area=document.createElement('div');area.className='chat-area';const head=document.createElement('div');head.className='chat-head';head.innerHTML='<strong>Rozmowa z '+r.display_name.replace(/[<>&]/g,'')+'</strong><span>tylko między Wami</span>';area.append(head);const stream=document.createElement('div');stream.className='chat-stream';for(const m of await api.matchMessages(r.match_id)){const wrap=document.createElement('div');wrap.className=m.mine?'chat-row mine':'chat-row';const p=document.createElement('p');p.className='chat-message';p.textContent=m.body;const time=document.createElement('time');time.textContent=new Date(m.created_at).toLocaleString('pl-PL',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});wrap.append(p,time);stream.append(wrap);}area.append(stream);const f=document.createElement('form');f.className='chat-form';const input=document.createElement('input');input.maxLength=1000;input.required=true;input.autocomplete='off';input.placeholder='Napisz wiadomość…';input.setAttribute('aria-label','Treść wiadomości');const send=document.createElement('button');send.className='primary';send.textContent='Wyślij';f.append(input,send);f.onsubmit=async e=>{e.preventDefault();send.disabled=true;try{await api.sendMessage(r.match_id,input.value);area.remove();box.classList.remove('chat-open');await openChat(r,box);}catch(x){notice(x.message,true);}finally{send.disabled=false;}};area.append(f);box.append(area);requestAnimationFrame(()=>{stream.scrollTop=stream.scrollHeight;input.focus();});}
 function paintMatches(rows){const list=$('matches-list');list.replaceChildren();$('matches-empty').hidden=!!rows.length;for(const r of rows){const a=document.createElement('article');a.className='match-card';const h=document.createElement('h4');h.textContent='Dopasowanie: '+r.display_name;const p=document.createElement('p');p.textContent=r.city+' · '+r.bio;const note=r.received_note?document.createElement('blockquote'):null;if(note){note.className='received-note';note.textContent='„'+r.received_note+'”';}const t=document.createElement('div');t.className='interest-list';tags(t,r.interests);const chat=document.createElement('button');chat.className='secondary';chat.textContent='Otwórz rozmowę';chat.onclick=()=>openChat(r,a).catch(e=>notice(e.message,true));const un=document.createElement('button');un.className='text-button danger';un.textContent='Usuń dopasowanie';un.onclick=async()=>{if(!confirm('Usunąć dopasowanie i rozmowę z '+r.display_name+'?'))return;await api.unmatch(r.match_id);paintMatches(await api.myMatches());};const block=document.createElement('button');block.className='text-button danger';block.textContent='Zablokuj';block.onclick=()=>blockPerson(r.display_name);a.append(...[image(r.photo_path,r.display_name),h,profileMeta(r),p,promptBlock(r),note,t,chat,un,block].filter(Boolean));list.append(a);}}
 function paintBlocks(rows){const list=$('blocked-list');list.replaceChildren();$('blocked-empty').hidden=!!rows.length;for(const r of rows){const a=document.createElement('article');a.className='match-card';const p=document.createElement('p');p.textContent=r.display_name+' · '+r.city;const b=document.createElement('button');b.className='secondary';b.type='button';b.textContent='Odblokuj';b.onclick=async()=>{await api.unblockPerson(r.display_name);paintBlocks(await api.myBlocks());notice('Osoba została odblokowana.');};a.append(p,b);list.append(a);}}
 const filterValues=()=>{const f=new FormData($('discovery-filters'));return{city:String(f.get('city')||''),interest:String(f.get('interest')||'')}};
 async function load(){const [own,next,matches,blocks]=await Promise.all([api.myDiscoveryProfile(),api.discoveryCards(filterValues()),api.myMatches(),api.myBlocks()]);profile=own;if(own){for(const k of ['display_name','city','bio','prompt_question','prompt_answer','age','identity','relationship_goal','min_age','max_age','max_distance_km'])$('discovery-form').elements[k].value=own[k]??'';$('discovery-form').elements.looking_for.value=(own.looking_for||['all'])[0];$('discovery-form').elements.interests.value=(own.interests||[]).join(', ');$('discovery-form').elements.visible.checked=own.visible;}$('location-status').textContent=own?.has_location?'Lokalizacja zapisana prywatnie. Dokładne współrzędne nie są pokazywane innym.':'Lokalizacja nie jest zapisana. Bez niej zasięg kilometrów nie ogranicza wyników.';$('clear-location').hidden=!own?.has_location;const current=$('current-photo');current.hidden=!own?.photo_path;if(own?.photo_path)current.querySelector('img').src=api.avatarUrl(own.photo_path);const unread=matches.reduce((n,x)=>n+Number(x.unread_count||0),0);tab.textContent=unread?'Poznaj ludzi ('+unread+')':'Poznaj ludzi';cards=next;paintCard();paintMatches(matches);paintBlocks(blocks);}
 function showMatch(name){const d=document.createElement('dialog');d.className='match-dialog';d.innerHTML='<div class="match-burst">♥</div><h2>Macie dopasowanie!</h2><p>Ty i '+name.replace(/[<>&]/g,'')+' chcecie się poznać.</p><button class="primary" type="button">Napisz wiadomość</button><button class="text-button" type="button">Wróć do kart</button>';const close=()=>{d.close();d.remove();};d.querySelector('.primary').onclick=()=>{close();$('matches-list').scrollIntoView({behavior:'smooth'});};d.querySelector('.text-button').onclick=close;root.append(d);d.showModal();}
 async function swipe(d){const r=cards[0];if(!r)return;const box=$('discovery-card'),note=$('discovery-note').value;box.classList.add(d==='like'?'fly-right':'fly-left');try{const x=await api.discoverySwipe(r.display_name,d,note);await new Promise(resolve=>setTimeout(resolve,180));cards.shift();$('discovery-note').value='';paintCard();if(x.matched){showMatch(r.display_name);paintMatches(await api.myMatches());}else notice(d==='like'?'Polubienie zapisane. Notatka będzie widoczna dopiero po dopasowaniu.':'Pominięto kartę. Możesz cofnąć dwa ostatnie pominięcia.');}catch(x){box.classList.remove('fly-right','fly-left');box.style.transform='';throw x;}}
 async function blockPerson(name){if(!confirm('Zablokować '+name+'? Kontakt natychmiast zniknie.'))return;await api.blockPerson(name);cards=cards.filter(x=>x.display_name!==name);paintCard();paintMatches(await api.myMatches());paintBlocks(await api.myBlocks());notice('Osoba została zablokowana.');}
 $('discovery-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.currentTarget),interests=String(f.get('interests')||'').split(',').map(x=>x.trim()).filter(Boolean),file=e.currentTarget.elements.photo.files[0],oldPhoto=profile?.photo_path||null,base={display_name:f.get('display_name'),city:f.get('city'),bio:f.get('bio'),interests,prompt_question:f.get('prompt_question'),prompt_answer:f.get('prompt_answer'),age:f.get('age'),identity:f.get('identity'),relationship_goal:f.get('relationship_goal'),looking_for:[f.get('looking_for')],min_age:f.get('min_age'),max_age:f.get('max_age'),max_distance_km:f.get('max_distance_km'),visible:e.currentTarget.elements.visible.checked,photo_path:oldPhoto};let cleanupWarning=false;await api.saveDiscoveryProfile(base);if(file){base.photo_path=await api.uploadAvatar(getUser().id,file);await api.saveDiscoveryProfile(base);if(oldPhoto&&oldPhoto!==base.photo_path)try{await api.deleteAvatar(oldPhoto);}catch{cleanupWarning=true;}}notice(cleanupWarning?'Wizytówkę i nowe zdjęcie zapisano, ale poprzedniego zdjęcia nie udało się jeszcze usunąć.':'Wizytówka i preferencje zostały zapisane.',cleanupWarning);await load();}catch(x){notice(x.message,true);const field=x.code?.startsWith('display_name')?'display_name':x.code==='city_invalid'?'city':x.code==='bio_invalid'?'bio':x.code==='interests_invalid'?'interests':x.code==='prompt_invalid'?'prompt_answer':x.code==='age_invalid'?'age':x.code==='age_range_invalid'?'min_age':null;if(field)e.currentTarget.elements[field].focus();}};
 $('remove-photo').onclick=async()=>{if(!profile?.photo_path||!confirm('Usunąć obecne zdjęcie z wizytówki?'))return;const path=profile.photo_path;try{await api.saveDiscoveryProfile({...profile,photo_path:null});await api.deleteAvatar(path);notice('Zdjęcie zostało usunięte.');await load();}catch(x){notice(x.message,true);}};
 $('set-location').onclick=()=>{if(!navigator.geolocation){notice('Ta przeglądarka nie obsługuje lokalizacji.',true);return;}$('set-location').disabled=true;navigator.geolocation.getCurrentPosition(async pos=>{try{await api.setDiscoveryLocation(pos.coords.latitude,pos.coords.longitude);notice('Lokalizacja została zapisana prywatnie i służy tylko do obliczania odległości.');await load();}catch(x){notice(x.message,true);}finally{$('set-location').disabled=false;}},()=>{$('set-location').disabled=false;notice('Nie udało się pobrać lokalizacji. Możesz zezwolić na nią później w ustawieniach przeglądarki.',true);},{enableHighAccuracy:false,timeout:12000,maximumAge:300000});};
 $('clear-location').onclick=async()=>{try{await api.clearDiscoveryLocation();notice('Lokalizacja została usunięta.');await load();}catch(x){notice(x.message,true);}};
 $('discovery-filters').onsubmit=e=>{e.preventDefault();load().catch(x=>notice(x.message,true));};$('discovery-pass').onclick=()=>swipe('pass').catch(x=>notice(x.message,true));$('discovery-like').onclick=()=>swipe('like').catch(x=>notice(x.message,true));$('discovery-undo').onclick=async()=>{try{if(undosLeft<1){notice('Wykorzystano dwa cofnięcia.');return;}if(!await api.undoLastPass()){notice('Nie ma pominięcia do cofnięcia.');return;}undosLeft--;$('discovery-undo').textContent='Cofnij pominięcie (zostały '+undosLeft+')';$('discovery-undo').disabled=undosLeft<1;notice('Przywrócono ostatnio pominiętą osobę.');await load();}catch(x){notice(x.message,true);}};$('discovery-block').onclick=()=>cards[0]&&blockPerson(cards[0].display_name).catch(x=>notice(x.message,true));$('discovery-report').onclick=async()=>{const r=cards[0],reason=r&&prompt('Krótko opisz powód zgłoszenia:');if(reason)try{await api.reportPerson(r.display_name,reason);notice('Zgłoszenie zostało zapisane.');}catch(x){notice(x.message,true);}};
 const card=$('discovery-card');card.onpointerdown=e=>{if(!cards[0]||e.pointerType==='mouse'&&e.button!==0)return;dragging=true;dragStart=e.clientX;dragX=0;card.setPointerCapture(e.pointerId);card.classList.add('dragging');};card.onpointermove=e=>{if(!dragging)return;dragX=e.clientX-dragStart;card.style.transform=`translateX(${dragX}px) rotate(${dragX/28}deg)`;card.classList.toggle('drag-like',dragX>35);card.classList.toggle('drag-pass',dragX<-35);};card.onpointerup=e=>{if(!dragging)return;dragging=false;card.releasePointerCapture(e.pointerId);card.classList.remove('dragging','drag-like','drag-pass');card.style.transform='';if(Math.abs(dragX)>85)swipe(dragX>0?'like':'pass').catch(x=>notice(x.message,true));};card.onpointercancel=()=>{dragging=false;card.classList.remove('dragging','drag-like','drag-pass');card.style.transform='';};
 return{load,clear(){cards=[];profile=null;undosLeft=2;$('discovery-undo').disabled=false;$('discovery-undo').textContent='Cofnij pominięcie (zostały 2)';paintCard();paintMatches([]);paintBlocks([]);},tab,panel};
}
